<?php
declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('notifications.manage');
if(is_post()){verify_csrf();$channel=strtoupper((string)input('channel'));$type=strtoupper(trim((string)input('type')));$title=trim((string)input('title'));$message=trim((string)input('message'));$userId=(int)input('user_id')?:null;if(!in_array($channel,['PUSH','SMS','EMAIL','IN_APP'],true)||$title===''||strlen($title)>190||$message===''||strlen($message)>5000||strlen($type)>80)flash('error','Complete all notification fields with valid values.');else{$pdo=db();$pdo->beginTransaction();try{if($userId){$check=$pdo->prepare('SELECT id FROM users WHERE id=?');$check->execute([$userId]);if(!$check->fetch())throw new RuntimeException('Recipient not found.');}$pdo->prepare('INSERT INTO notifications(user_id,type,channel,title,message,status) VALUES(?,?,?,?,?,"QUEUED")')->execute([$userId,$type?:'GENERAL',$channel,$title,$message]);$notificationId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO notification_logs(notification_id,status,response_summary) VALUES(?,"QUEUED","Queued by administrator")')->execute([$notificationId]);audit_log((int)admin()['id'],'NOTIFICATION_QUEUED','notifications',(string)$notificationId,null,['channel'=>$channel,'user_id'=>$userId]);$pdo->commit();flash('success','Notification queued for delivery.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Could not queue notification.':$e->getMessage());}}redirect('/admin/notifications/index.php');}
$rows=db()->query('SELECT n.*,u.name FROM notifications n LEFT JOIN users u ON u.id=n.user_id ORDER BY n.id DESC LIMIT 100')->fetchAll();$users=db()->query("SELECT id,name,mobile FROM users WHERE status='ACTIVE' ORDER BY name LIMIT 1000")->fetchAll();$pageTitle='Notifications';$pageSubtitle='Queue messages for configured delivery workers';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><h2>Compose notification</h2><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Recipient</label><select name="user_id"><option value="">All users</option><?php foreach($users as $u):?><option value="<?=e($u['id'])?>"><?=e($u['name'].' · '.$u['mobile'])?></option><?php endforeach?></select></div><div class="field"><label>Channel</label><select name="channel"><option>IN_APP</option><option>PUSH</option><option>SMS</option><option>EMAIL</option></select></div><div class="field"><label>Type</label><input name="type" value="GENERAL" maxlength="80"></div><div class="field"><label>Title</label><input name="title" maxlength="190" required></div><div class="field full"><label>Message</label><textarea name="message" maxlength="5000" required></textarea></div><div class="field full"><button class="btn">Queue notification</button></div></form></section><section class="panel"><h2>Delivery queue</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Recipient</th><th>Channel</th><th>Title</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name']??'All users')?></td><td><?=e($r['channel'])?></td><td><?=e($r['title'])?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No notifications have been queued.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
